def find_jsonl_files(directory, max_depth=2):
    """Find jsonl files recursively up to max_depth"""
    jsonl_files = []
    if max_depth <= 0:
        return jsonl_files

    try:
        items = os.listdir(directory)
    except:
        return []

    for item in items:
        full_path = os.path.join(directory, item)
        if os.path.isfile(full_path):
            if item.endswith('.jsonl'):
                jsonl_files.append(full_path)
        elif os.path.isdir(full_path):
            jsonl_files.extend(find_jsonl_files(full_path, max_depth - 1))

    return jsonl_files

